    root, quality, bass = parse_chord(symbol)
    prefer = "flat" if root.endswith("b") else "sharp"
    base = midi(f"{root}{octave}")
    notes = [name_of(base + step, prefer) for step in QUALITIES[quality]]
    if bass is not None:
        notes.insert(0, f"{bass}{octave - 1}")
    return notes


