        self.assertEqual(interval("E4", "C4"), (-4, "-M3"))
        self.assertEqual(interval("C4", "C5"), (12, "P8"))
        self.assertEqual(interval("C4", "D5"), (14, "M2+1"))
        self.assertEqual(interval("C4", "C4"), (0, "P1"))
        self.assertEqual(interval("Bb3", "D4"), (4, "M3"))
